// Merges the two upstream shapes -- rules-router items (already carry
// classification/confidence/route) and LLM items (carry OpenRouter's raw chat
// completion in $json.choices[0].message.content, still needing the rules-router
// fields from the ORIGINAL Mask+normalize item, read back via node reference
// since the HTTP node's own output replaced $json entirely) -- into ONE shape,
// then applies the confidence gate: <0.7 -> needs_review.
var j = $json;
var isLlmResponse = j.choices !== undefined || j.id !== undefined && j.object === 'chat.completion';

var classification, confidence, isBuyer, draftedReply, senderRef2, subjectRef2, receivedAt, idemKey, route, sourceOrig;

if (isLlmResponse) {
  var raw = '';
  try {
    raw = j.choices[0].message.content || '';
  } catch (e) {
    raw = '';
  }
  var parsed = {};
  try {
    var cleaned = raw.replace(/```json|```/g, '').trim();
    parsed = JSON.parse(cleaned);
  } catch (e) {
    parsed = {};
  }
  classification = parsed.classification || 'unknown';
  confidence = parsed.confidence !== undefined ? Number(parsed.confidence) : 0.5;
  isBuyer = parsed.is_buyer === true || classification === 'lead';
  draftedReply = String(parsed.drafted_reply || '').slice(0, 2000);
  route = 'model';

  var origIdx = $itemIndex;
  var orig = {};
  try {
    orig = $('Guard: cap').all()[origIdx].json;
  } catch (e) {
    orig = {};
  }
  senderRef2 = orig.sender_ref || null;
  subjectRef2 = orig.subject_ref || null;
  receivedAt = orig.received_at || null;
  idemKey = orig.idempotency_key || null;
} else {
  classification = j.classification || 'unknown';
  confidence = Number(j.confidence !== undefined ? j.confidence : 0.4);
  isBuyer = classification === 'lead';
  draftedReply = '';
  route = j.route || 'rules';
  senderRef2 = j.sender_ref || null;
  subjectRef2 = j.subject_ref || null;
  receivedAt = j.received_at || null;
  idemKey = j.idempotency_key || null;
}

var needsReview = confidence < 0.7;

return { json: {
  classification: needsReview ? 'needs_review' : classification,
  original_classification: classification,
  is_buyer: isBuyer,
  drafted_reply: draftedReply,
  confidence: confidence,
  route: route,
  received_at: receivedAt,
  sender_ref: senderRef2,
  subject_ref: subjectRef2,
  idempotency_key: idemKey,
  needs_review: needsReview
} };

// ===================== WRITE WHITELIST GATE =====================
// Same chokepoint pattern as EP06's WRITE WHITELIST GATE: reads any caller-supplied
// 'kind' FIRST and throws on anything that is not the allowed value (mirrors EP06's
// "j.kind !== 'pause' -> throw"), THEN builds the write body itself from constants --
// callers never supply the body -- so the only object that can ever reach the
// mailbox is {kind:'label', name:'EP07/<classification>'}. There is no code path
// here that can emit a send, a reply, a delete, or a move. Throws, never skips.
var ALLOWED_KIND = 'label';
var ALLOWED_PREFIX = 'EP07/';

var out = [];
for (var i = 0; i < $input.all().length; i++) {
  var j = $input.all()[i].json;

  // Refute-first gate: a crafted/corrupted item carrying an explicit 'kind'
  // field (the real pipeline never sets one upstream -- Write inbox row's
  // output has no 'kind' key at all) is refused unless it already says 'label'.
  if (Object.prototype.hasOwnProperty.call(j, 'kind') && j.kind !== ALLOWED_KIND) {
    throw new Error('WRITE WHITELIST: refusing item of kind "' + j.kind + '". Only kind=label may reach the mailbox.');
  }

  // ON CONFLICT DO NOTHING can return zero columns for a duplicate row -- skip
  // silently rather than crash on a legitimate idempotent no-op (a row with
  // neither an id nor a classification and no smuggled kind is just empty).
  if (j.id === undefined && j.classification === undefined && !Object.prototype.hasOwnProperty.call(j, 'kind')) {
    continue;
  }

  var candidate = { kind: 'label', name: ALLOWED_PREFIX + String(j.classification || 'needs_review') };

  if (candidate.kind !== ALLOWED_KIND) {
    throw new Error('WRITE WHITELIST: refusing kind "' + candidate.kind + '". Only kind=label may reach the mailbox.');
  }
  if (candidate.name.indexOf(ALLOWED_PREFIX) !== 0) {
    throw new Error('WRITE WHITELIST: refusing label name outside the ' + ALLOWED_PREFIX + ' namespace.');
  }
  var keys = Object.keys(candidate);
  if (keys.length !== 2 || keys.indexOf('kind') === -1 || keys.indexOf('name') === -1) {
    throw new Error('WRITE WHITELIST: constructed body failed its own assertion: ' + JSON.stringify(candidate));
  }

  out.push({ json: Object.assign({}, j, { write: candidate }) });
}

return out;

// One summary item, read straight off the execution panel. Runs regardless of
// which branch (dry-run or would-apply) each item took.
function all(name) {
  try {
    return $(name).all().map(function (i) { return i.json; });
  } catch (e) {
    return [];
  }
}

var masked = all('Mask + normalize');
var routed = all('Rules router');
var gated = all('WRITE WHITELIST GATE');
var written = all('Write inbox row');

var rulesHandled = 0, modelHandled = 0, leads = 0, needsReview = 0, spamCount = 0, techCount = 0, existingCount = 0;
for (var i = 0; i < written.length; i++) {
  var w = written[i];
  if (w.route === 'rules') rulesHandled++;
  if (w.route === 'model') modelHandled++;
  if (w.original_classification === 'lead' || w.classification === 'lead') leads++;
  if (w.classification === 'needs_review') needsReview++;
  if (w.original_classification === 'spam') spamCount++;
  if (w.original_classification === 'technical') techCount++;
  if (w.original_classification === 'existing_client') existingCount++;
}

var cfg = {};
try {
  cfg = $('Load caps').first().json || {};
} catch (e) {
  cfg = {};
}

return [{ json: {
  msgs_in: masked.length,
  rules_handled: rulesHandled,
  model_handled: modelHandled,
  leads: leads,
  needs_review: needsReview,
  spam: spamCount,
  technical: techCount,
  existing_client: existingCount,
  sent: 0,
  labels_gated: gated.length,
  rows_written: written.length,
  dry_run: cfg.dry_run === true
} }];
